```r
import rasterio as rio
from shapely.geometry import Polygon, Point, MultiPolygon

def is_inside(point, polygon):
    try:
        point_on_edge = polygon.contains(point)
    except:
        return False

    if not point_on_edge:
        return False

    for edge in polygon.boundary.edges:
        if edge[0].y == edge[1].y: # A horizontal line segment.
            return (point.x >= edge[1].x and point.x <= edge[0].x) or (point.x <= edge[1].x and point.x >= edge[0].x)
        else: # A vertical line segment.
            return (point.y >= edge[1].y and point.y <= edge[0].y) or (point.y <= edge[1].y and point.y >= edge[0].y)
    else:
        if (point.x >= polygon.bounds.minx and point.x <= polygon.bounds.maxx) and (point.y >= polygon.bounds.miny and point.y <= polygon.bounds.maxy):
            return True
        else:
            return False
```
